stateModel.stateShapeTypeScript:
type PassengerType = string          // keys come from config (e.g. 'adult' | 'child' | 'infant'), not hardcoded
type ISODate = string                // 'YYYY-MM-DD', local to the departure airport. Never a JS Date.
type Money = { amountMinor: number; currency: string }   // minor units; currency exponent comes from ISO 4217 (JPY 0, USD 2, KWD 3)

type Passenger = {
  id: string                         // stable for the whole booking; never regenerated
  type: PassengerType
  infantOnLap?: boolean              // A · unverified: infants "in seat or on lap". Lap infants need no seat.
}

type BookingState = {
  search: {
    tripType: 'return' | 'one-way' | 'multi-city'                 // A · unverified
    journeys: { id: string; from: string; to: string; date: ISODate }[]
    cabin: 'economy' | 'premium-economy' | 'business' | 'first'   // Official: four cabins
  }
  passengers: Passenger[]
  selections: Record<string, {       // journeyId →
    offerId: string                  // the flight option chosen on results
    fareId: string                   // the fare family chosen for it
    segmentIds: string[]             // the flights in this journey, in order
  } | null>
  seats: Record<string, Record<string, string | null>>          // segmentId → passengerId → seatId
  payment: { currency: string; useMiles: boolean }
  quote: Quote | null
  quoteStatus: 'idle' | 'pending' | 'fresh' | 'stale' | 'error'
}

type Quote = {
  id: string                         // sent back with the payment request; the server rejects a stale id
  expiresAt: string                  // ISO timestamp
  lineItems: { kind: 'fare' | 'tax' | 'seat' | 'extra'; label: string; ref?: string; amount: Money }[]   // label is localised by the server
  total: Money
  miles?: number                     // Cash+Miles (Official)
}
